package app.lensly.app.export

import app.lensly.app.AddressBookEntry
import app.airvault.chains.evm.ethereumMainnet
import app.airvault.chains.evm.evmAddressOf
import app.airvault.core.model.Curve
import app.lensly.core.btc.BtcAccount
import app.lensly.core.btc.BtcNetwork
import app.lensly.core.btc.ScriptType
import app.lensly.core.wallet.AccountAddresses
import app.lensly.core.wallet.HdWallet
import app.lensly.core.wallet.Mnemonic
import java.util.UUID
import kotlin.random.Random

/**
 * The demo pairing for the size check: the public BIP39 test wallet, with 12 Ethereum accounts (some named, labelled or grouped), three
 * stored Bitcoin accounts (Native Segwit and Taproot on mainnet, Native Segwit on testnet4), and an Address Book of 50 entries. It holds no real key. [FRAMES_BROTLI] is the code
 * that Lensly's encoder writes for it. The instrumented test checks that the encoder still writes these frames, and Lumio's test reads them
 * back.
 */
object DemoPairingGolden {
    private val WORDS = ("abandon ".repeat(23) + "art").split(" ")
    private val NAMES = listOf(
        "Main", "Daily spend", "Cold storage", "Savings 2026", "Work", "Hot wallet", "Test", "Escrow", "Payroll Q4", "Ledger backup", "Charity",
        "Reserve",
    )
    private val GROUPS = listOf("Savings", "Trading", "Cold", "Payroll", "Rent", "Donations", "Exchange", "Staking", "Family", "Business", "Travel", "Grants", "Team", "Ops")
    private val CONTACTS = listOf("Alice", "Bob", "Exchange deposit", "Cold storage", "Ledger", "Mum", "Dad", "Office", "Landlord", "Coffee shop", "Payroll Acme")
    private val BOOK_LABELS = listOf("Cold", "Trading", "Family", "Vendor")

    /** The demo pairing. Its keys and addresses are derived from the test wallet, so Lumio's importer accepts them. */
    fun payload(): PairingPayload {
        val seed = Mnemonic.of(WORDS).use { it.deriveSeed("") }
        val wallet = HdWallet(seed)
        val fingerprint = wallet.masterFingerprint
        // The Bitcoin accounts the owner stores: one Native Segwit and one Taproot on mainnet, and one Native Segwit on testnet4.
        val bitcoin = listOf(
            BtcAccount.fromSeed(seed, BtcNetwork.MAINNET, ScriptType.NATIVE_SEGWIT, 0).watchOnly(),
            BtcAccount.fromSeed(seed, BtcNetwork.MAINNET, ScriptType.TAPROOT, 0).watchOnly(),
            BtcAccount.fromSeed(seed, BtcNetwork.TESTNET4, ScriptType.NATIVE_SEGWIT, 0).watchOnly(),
        )
        val bitcoinNames = listOf("Bitcoin main 1", "Bitcoin main 2", "Bitcoin test 1")
        val random = Random(20261116)
        val ethereum = List(12) { account ->
            PairingAccount(
                export = keyExport(
                    ethereumMainnet,
                    fingerprint,
                    accountSteps(44, 60, account, 0, 0),
                    Curve.SECP256K1,
                    AccountAddresses.addressXpub(wallet.accountXpub(account), 0).publicKey,
                ),
                name = if (account % 2 == 0) NAMES[account] else "Account ${account + 1}",
                label = if (account % 4 == 0) "Cold" else null,
                group = if (account % 3 == 0) GROUPS[account] else null,
            )
        }
        val bitcoinAccounts = bitcoin.mapIndexed { i, account ->
            PairingAccount(export = watchOnlyExportOf(account, fingerprint), name = bitcoinNames[i], label = null, group = null)
        }
        return PairingPayload(
            fingerprint = wallet.masterFingerprint.toLong() and 0xFFFFFFFFL,
            name = "My AirVault wallet",
            autoNameBase = "My AirVault wallet",
            accounts = ethereum + bitcoinAccounts,
            addressBook = List(50) { i ->
                val address = if (i % 5 != 4) {
                    checkNotNull(evmAddressOf("0x" + random.nextBytes(20).joinToString("") { "%02x".format(it) }))
                } else {
                    bitcoin[i % bitcoin.size].receiveAddress(i)
                }
                AddressBookEntry(
                    id = UUID(random.nextLong(), random.nextLong()).toString(),
                    address = address,
                    name = "${CONTACTS[i % CONTACTS.size]} ${i + 1}",
                    label = if (i % 3 == 0) BOOK_LABELS[i % BOOK_LABELS.size] else null,
                )
            },
        )
    }

    /** The frames of [payload] as Lensly's encoder writes them: the body recorded on a device, in a version-6 code. */
    val FRAMES_BROTLI: List<String> = listOf(
        "UR:X-AIRVAULT-PAIRING/1-",
        "UR:X-AIRVAULT-PAIRING/2-",
        "UR:X-AIRVAULT-PAIRING/3-",
        "UR:X-AIRVAULT-PAIRING/4-",
        "UR:X-AIRVAULT-PAIRING/5-",
        "UR:X-AIRVAULT-PAIRING/6-",
        "UR:X-AIRVAULT-PAIRING/7-",
        "UR:X-AIRVAULT-PAIRING/8-",
        "UR:X-AIRVAULT-PAIRING/9-",
        "UR:X-AIRVAULT-PAIRING/10-",
        "UR:X-AIRVAULT-PAIRING/11-",
    )
}
